/** The photo for a requirement card: the template's own, else the trade's. */
export const photoFor = (template, tradeId) => REQUIREMENT_PHOTOS[`${template}:${tradeId}`] ?? REQUIREMENT_PHOTOS[`t:${tradeId}`] ?? null
